(x, y, t) => {
  const cx = 240, cy = 120;
  const vort = Math.sin(t*0.15)*0.5 + Math.cos(t*0.12)*0.3;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.01+t*0.18)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.012-t*0.22)*8;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.14, 2.1],
    [400+Math.cos(t*0.38+2)*60, 220+Math.sin(t*0.48)*40, 0.11, 1.8]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const d2 = Math.sqrt((sx*0.5-sX*0.5)**2+(sy*0.5-sY*0.5)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2 += Math.sin(d2*f*1.8-t*sp*0.8+0.7);
    iS2 += Math.cos(d2*f*1.3+t*sp*0.4-1.2);
  }
  const act=(aS+aS2*0.4)/8, inh=(iS+iS2*0.4)/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.07*Math.cos(t*0.1)+sy*0.05*Math.sin(t*0.13)+t*1.8)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.08+ang*2*vort-t*2.2)*0.2;
  const lap = (sx<2||sx>477||sy<2||sy>236) ? 0 : 
    (Math.sin((sx+2)*0.04+sy*0.025+t*0.8)+Math.sin((sx-2)*0.04+sy*0.025+t*0.8)
    +Math.sin(sx*0.04+(sy+2)*0.025+t*0.8)+Math.sin(sx*0.04+(sy-2)*0.025+t*0.8))/2-bg;
  const diffusion = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + lap*0.15)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.08;
  const blend = diffusion*0.65 + cell*0.2 + micro, v = blend*0.5+0.5;
  const pal = [[5,12,45],[10,50,90],[12,95,120],[18,145,130],[45,175,120],[140,190,80],[210,175,55],[220,130,60],[185,70,55],[120,35,55],[55,18,65],[5,12,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.8+Math.sin(diffusion*Math.PI)*0.2;
  const edge=Math.abs(diffusion)>0.65?1.2:Math.abs(diffusion)>0.4?1.05:0.95;
  const glow=Math.max(0,diffusion*0.15);
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*80)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*60)|0)
  ];
}
